// Research hero: a circularly / linearly / elliptically polarized wave in 3D.
// Glowing E-field (cyan) and H-field (amber) vectors along +z, the E-tip helix,
// its shadow projections on the walls, and an XY "Lissajous" inset with persistence.
import { canvasScene } from "./core/canvas.js";
import { profile } from "../data/profile.js";
import { lowPower } from "./core/manager.js";

let instance, cleanup;

export function init(container, options = {}) {
  destroy();
  let target = 1,
    ellipticity = 1;
  const trail = [];
  const readout = container.parentElement.querySelector("[data-ar]");
  const D = profile.diagrams.polarization;
  const N = lowPower ? 22 : 38;

  instance = canvasScene(
    container,
    ({ ctx, w, h, t, dt, still, colors: c }) => {
      ellipticity = still
        ? target
        : ellipticity + (target - ellipticity) * Math.min(1, dt * 5);
      const phase = t * 1.7;
      const yaw = 0.62 + 0.2 * Math.sin(t * 0.16);
      const pitch = 0.3;
      const scale = Math.min(w * 0.2, h * 0.34);
      const cx = w * 0.44,
        cy = h * 0.55;
      const cyw = Math.cos(yaw),
        syw = Math.sin(yaw),
        cp = Math.cos(pitch),
        sp = Math.sin(pitch);
      // world: X = propagation, Y = up (Ey), Z = depth (Ex)
      const P = (z, ex, ey) => {
        const X = z * 2.3,
          Y = ey,
          Z = ex;
        const x1 = X * cyw - Z * syw,
          z1 = X * syw + Z * cyw;
        const y2 = Y * cp - z1 * sp,
          z2 = Y * sp + z1 * cp;
        const s = 5 / (5 + z2);
        return [cx + x1 * s * scale, cy - y2 * s * scale];
      };
      const line = (pts, color, width, blur, alpha = 1, dash) => {
        ctx.save();
        ctx.globalAlpha = alpha;
        ctx.strokeStyle = color;
        ctx.lineWidth = width;
        ctx.shadowColor = color;
        ctx.shadowBlur = blur;
        if (dash) ctx.setLineDash(dash);
        ctx.beginPath();
        pts.forEach((p, i) => (i ? ctx.lineTo(...p) : ctx.moveTo(...p)));
        ctx.stroke();
        ctx.restore();
      };
      const E = (z) => {
        const p = z * Math.PI * 4 - phase;
        return [Math.cos(p), Math.sin(p) * ellipticity];
      };

      // walls: floor (Ey = -1.25) and back wall (Ex = -1.25) grids
      ctx.save();
      ctx.globalAlpha = 0.5;
      for (let i = 0; i <= 10; i++) {
        const z = -1 + i * 0.2;
        line([P(z, -1.25, -1.25), P(z, 1.25, -1.25)], c.line, 1, 0);
        line([P(z, -1.25, -1.25), P(z, -1.25, 1.25)], c.line, 1, 0);
      }
      for (let i = 0; i <= 4; i++) {
        const v = -1.25 + i * 0.625;
        line([P(-1, v, -1.25), P(1, v, -1.25)], c.line, 1, 0);
        line([P(-1, -1.25, v), P(1, -1.25, v)], c.line, 1, 0);
      }
      ctx.restore();

      // shadow projections of the field components
      const zs = Array.from({ length: 161 }, (_, i) => -1 + (i / 160) * 2);
      line(
        zs.map((z) => P(z, E(z)[0], -1.25)),
        c.cyan,
        1.2,
        6,
        0.45,
      );
      line(
        zs.map((z) => P(z, -1.25, E(z)[1])),
        c.phosphor,
        1.2,
        6,
        0.45,
      );

      // propagation axis
      line([P(-1.15, 0, 0), P(1.2, 0, 0)], c.muted, 1, 0, 0.8, [4, 5]);

      ctx.globalCompositeOperation = "lighter";
      // H-field vectors (amber) and E-field vectors (cyan)
      for (let i = 0; i <= N; i++) {
        const z = -1 + (i / N) * 2;
        const [ex, ey] = E(z);
        const o = P(z, 0, 0);
        line([o, P(z, -ey * 0.72, ex * 0.72)], c.amber, 1.1, 6, 0.55);
        line([o, P(z, ex, ey)], c.cyan, 1.3, 8, 0.85);
      }
      // E-tip helix: wide glow + bright core
      const helix = zs.map((z) => P(z, ...E(z)));
      line(helix, c.cyan, 7, 22, 0.35);
      line(helix, c.cyan, 2.6, 12, 1);
      line(helix, "#ffffff", 0.8, 0, 0.7);
      // bright wavefront plane marker travelling with the wave
      const zf = ((t * 0.27) % 2) - 1;
      const ring = Array.from({ length: 49 }, (_, i) => {
        const a = (i / 48) * Math.PI * 2;
        return P(
          zf,
          Math.cos(a) * 1.05,
          Math.sin(a) * 1.05 * Math.max(ellipticity, 0.04),
        );
      });
      line(ring, c.phosphor, 1.4, 12, 0.7);
      ctx.globalCompositeOperation = "source-over";

      // XY inset: tip trace with persistence (like a scope in XY mode)
      const r = Math.min(w * 0.1, h * 0.17, 60),
        ix = w - r - 26,
        iy = r + 26;
      ctx.strokeStyle = c.line;
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.arc(ix, iy, r, 0, Math.PI * 2);
      ctx.moveTo(ix - r - 8, iy);
      ctx.lineTo(ix + r + 8, iy);
      ctx.moveTo(ix, iy - r - 8);
      ctx.lineTo(ix, iy + r + 8);
      ctx.stroke();
      const tip = [
        ix + Math.cos(-phase) * r,
        iy - Math.sin(-phase) * r * ellipticity,
      ];
      if (!still) {
        trail.push(tip);
        if (trail.length > 70) trail.shift();
      }
      ctx.globalCompositeOperation = "lighter";
      for (let i = 1; i < trail.length; i++) {
        const a = i / trail.length;
        line([trail[i - 1], trail[i]], c.cyan, 2.2, 10, a * 0.9);
      }
      line([[ix, iy], tip], c.phosphor, 1.6, 10, 1);
      ctx.fillStyle = "#ffffff";
      ctx.shadowColor = c.cyan;
      ctx.shadowBlur = 14;
      ctx.beginPath();
      ctx.arc(...tip, 3, 0, Math.PI * 2);
      ctx.fill();
      ctx.shadowBlur = 0;
      ctx.globalCompositeOperation = "source-over";

      // labels
      ctx.font = '10px "JetBrains Mono", monospace';
      ctx.fillStyle = c.muted;
      ctx.fillText(D.tip, ix - r, iy + r + 22);
      ctx.fillText(D.axis, 14, h - 14);
      ctx.fillStyle = c.cyan;
      ctx.fillText(`■ ${D.e}`, 14, 22);
      ctx.fillStyle = c.amber;
      ctx.fillText(`■ ${D.h}`, 110, 22);
      if (readout)
        readout.textContent = `${D.ar} ${ellipticity < 0.005 ? "∞" : (20 * Math.log10(1 / ellipticity)).toFixed(1)} ${D.units}`;
    },
    options,
  );
  const buttons = [
    ...container.parentElement.querySelectorAll("[data-polarization]"),
  ];
  const select = (event) => {
    const button = event.currentTarget;
    target = [0, 1, 0.45][Number(button.dataset.polarization)];
    trail.length = 0;
    buttons.forEach((b) =>
      b.setAttribute("aria-pressed", String(b === button)),
    );
    instance.render();
  };
  buttons.forEach((b) => b.addEventListener("click", select));
  cleanup = () =>
    buttons.forEach((b) => b.removeEventListener("click", select));
  return instance;
}

export function destroy() {
  cleanup?.();
  instance?.destroy();
  instance = null;
}
